create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema storage;
create table auth.users(id uuid primary key);
create table public.users(id uuid primary key references auth.users(id) on delete cascade);
create table public.trade_records(id int primary key,user_id uuid references auth.users(id));
create table public.daily_profit(id int primary key,user_id uuid);
create table public.fundamental_analysis(id int primary key,user_id uuid);
create table public.watchlist(user_id uuid references auth.users(id) on delete cascade);
create table public.journal_settings(user_id uuid references auth.users(id) on delete cascade);
create table public.journal_reports(user_id uuid references auth.users(id) on delete cascade);
create table public.watchlist_notes(user_id uuid references auth.users(id) on delete cascade);
create table public.follows(follower_id uuid references public.users(id) on delete cascade,following_id uuid references public.users(id) on delete cascade);
create table public.stock_comments(user_id uuid references public.users(id) on delete cascade);
create table public.news("user" uuid references public.users(id) on delete cascade);
create table public.technical_analysis("user" uuid references public.users(id) on delete cascade);
create table storage.objects(bucket_id text,name text,owner uuid,owner_id text);
